"Anyone remember why the sky is a portal?":"なんで空がポータルなのか、誰か覚えてるか?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"シャフトに飛び込むと敵のところに出るらしい。試す気はないけどな。",
"The Swarm painted their visors red again. Show-offs.":"スウォームの連中、またバイザーを赤く塗りやがった。目立ちたがりめ。",
"Ore, ore… when do we get some oil?":"鉱石、鉱石…潤滑油はいつ支給されるんだ?",
