"robot war · the sky is a portal":"ロボット戦争 · 空はポータル",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"隕石へようこそ!あなたはコンソーシアムの戦闘ロボットだ。マウスで見回し、WASDで移動しろ。",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"ジェットパック:Shiftをタップでホップ、長押しで飛行。エネルギーは地上で回復する。",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"射撃は左クリック。照準は右クリック:ズーム付きでより正確。数発撃ってみよう。",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"リロードはR。弾は中距離、20〜50メートルで最も効く。",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"ロケット弾はQ。戦車や建物に有効。ロケット弾を撃ってみよう。",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"上部にストラテジストの命令がある。緑の矢印に沿って走れ:ルート上ではスプリントできる。ポイントを制圧するにはビーコンの近くに留まれ。",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"分隊が援護してくれる:左側に彼らのポートレートと体力がある。遅れたら、待ってくれと頼んでくる。",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — 戦闘を離れずにユニットを素早く切り替え:戦闘に最も近い分隊か戦車へ飛び移る。試してみよう。",
"Next to a tank or turret press E to take control. Or just carry on.":"戦車やタレットの近くでEを押すと操縦できる。そのまま進んでもいい。",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"次は戦略だ。右上の「◩ ストラテジー」をタップしろ — 戦場を真上から見下ろせる。",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"次は戦略だ。{0}(または左上の「◩ ストラテジー」)を押せ — 戦場を真上から見下ろせる。",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"ストラテジストではガイドが手助けしてくれる:上のウィンドウが次の行動を示し、枠がボタンを、リングがマップ上の場所を指す。ガイドのヒントを3つこなせ。",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"分隊を選択して緑の「▶ 憑依」ボタンをタップしろ — その兵士として再び戦闘に入る。お前が撃っている間は、AI戦略官が軍を指揮する。",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"分隊を選択して{0}か緑の「▶ 憑依」を押せ — その兵士として再び戦闘に入る(未選択なら自分の機体)。お前が撃っている間は、AI戦略官が軍を指揮する。",
