"Attack-move":"攻撃移動",
"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"続けて地面をクリック(タップ): 移動しながら戦う。敵に対しては攻撃。右クリックと同じ。",
