"Squads jet up through the dome portal and land at the enemy.":"分隊がジェットパックで飛び、ドームのポータルを抜けて敵地に降下する。",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"選択中の兵士・戦車・タレットを自分で操作する。戦闘中に同じキーを押すと戦略に戻る。",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"兵士4人: 突撃兵、重機関銃兵、ロケット兵、衛生兵。",
"Autonomous combat vehicle: cannon and MG, barrage, smoke, overdrive.":"自律戦闘車両: 砲と機関銃、一斉射撃、スモーク、オーバードライブ。",
"Fast flying gunner, good against infantry.":"高速で飛ぶ射撃手。歩兵に有効。",
"Elite squad with strong jetpacks — can sky-assault through the dome.":"強力なジェットパックを持つ精鋭分隊 — ドームを抜けて降下作戦が可能。",
"A lone railgun sniper.":"レールガンを持つ単独の狙撃兵。",
"Fast scout: sees far and spots enemies.":"高速偵察兵: 遠くまで見渡し、敵を発見する。",
"A squad drops from orbit right at the front line.":"分隊が軌道から前線のすぐ近くに降下する。",
"Jetpacks II: infantry reaches the dome and can sky-assault.":"ジェットパックII: 歩兵がドームまで届き、降下作戦が可能になる。",
