"New in v6.3":"v6.3の新要素",
"New in v6.2":"v6.2の新要素",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"鉱石の見た目を刷新: 鉱脈は黒い玄武岩の上で光るエメラルドのカット結晶、火花と緑の靄つき。エクストラクターは六角形の台座、ハニカムドーム、緑のビーコンを戴く格子状の塔(帯と旗はチームカラー)",
"New in v6.1":"v6.1の新要素",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Battlefield風の専用クラス(U、死亡後は数字キー): 利用可能なら自動でそのクラスで復活する",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"車両を一人称視点で操作(V — 外/コックピット)。穏やかなエイムアシストは設定で",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"コアからの脱出が簡単に: スペース — 縦穴へ、B — カプセルで地表へ。能力効果は死亡時にリセット",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"終わりなき成長: 将軍とマーシャル★、キャリアレベル、武器の熟練度とアタッチメント、勲章、デイリー契約 — キャリア画面",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"戦略:ホイールでスムーズズーム、ユニット上のアイコンとラベル(Alt — 全表示)、左に「部隊 / 建物」パネル",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"右クリック — アタックムーブ、右ダブルクリック — 撃ちながら行軍。まれな命令は「その他の命令 ▾」に。ボタンの重複なし",
"New in v6":"v6の新要素",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"シューター並みの射撃:ヒットスキャン弾、720 RPMのライフル、MG、反動、右クリックで照準、マガジンとRでリロード、ヒットマーカー",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"重力が強化、ジェットパックの反応が向上、Zまたは空中でジェット2回押しでダッシュ。ユニット切り替え時に武器がついて飛ばなくなった",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"工兵:工兵を選び、建物を選んで設計図を設置。鉱脈にエクストラクター。「鉱石」をクリックすると収入源と増やし方を確認",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"グレーのボタンは理由と解決ボタンを表示。大きなボタン、「進行中」バー、「▶ 憑依」、Tabがモード切替キー",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"ジャンプや反転のない戦略カメラ、カーソル位置へのズーム、ドラッグできるミニマップ",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"新兵器:レイダー「ジャッカル」、MLRS「グラード」(誘導ロケット弾)、迫撃砲「ハンマー」。蜂群は「ワスプ」「ハイブ」「トレビュシェット」を獲得",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"AI戦略官は命令を乱発せず、音声も連発しない。戦闘はあなたの近くで発生。B — 再配置、Shift+B — 戦闘の最中へ、コンパス、H — 目標の切り替え",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"自由行動(K)と単独行動(J)、F2でプリセット。Escで一時停止と再開。セーブ:スロット、ファイルのエクスポートとインポート",
"New in v5.3":"v5.3の新要素",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"飛行:隕石から離れるほど重力が強まり、空中でCがブレーキ、推力の操舵が鋭く。ポータルでの立ち往生がなくなった",
"New in v5":"v5の新要素",
