"Curator":"ガイド",
"Guides you during play: arrows to buttons and marks on the map. Turn it off any time (also in Settings).":"プレイ中に何をどこでやるかを教えてくれる。ボタンを指す矢印とマップ上のマーク付き。いつでもオフにできる(設定でも可)。",
"queue {0}/5":"キュー {0}/5",
"Select the HQ and train a builder (50 ore) — click to open the HQ panel":"司令部を選んで工兵を要請しよう(鉱石50)— クリックで司令部のパネルが開く",
"Builders are trained only at the HQ: select the HQ (click it or F2) — its production panel opens on the right. Same for the mech factory, drone hub, airdock and outpost":"工兵は司令部でしか要請できない。司令部を選ぶ(クリックまたはF2)と、右に生産パネルが開く。メカ工場、ドローンハブ、エアドック、前哨基地も同じ",
"The Build tab opens when a builder is selected; a \"Select nearest builder\" button; Z X C V B N K pick a builder automatically":"工兵を選ぶと「建設」タブが開く。「最寄りの工兵を選択」ボタンあり。Z X C V B N Kキーは工兵を自動で選ぶ",
"The Curator replaces the strategy tutorial: it suggests what to do as you play, points at the button and marks the map; turn it off on the panel or in Settings":"ストラテジーのチュートリアルの代わりにガイドが登場。プレイ中に何をすべきか教え、矢印でボタンを、マークでマップ上の場所を示す。パネルのボタンまたは設定でオフにできる",
"Developer mode (main menu): unlimited ore, everything unlocked, instant build, the Arsenal — any weapon, class, vehicle, target dummies; your career is untouched":"開発者モード(メインメニュー):鉱石無限、全解放、即時建設、「アーセナル」— 好きな武器、クラス、車両、標的ダミー。キャリアは変化しない",
"Phone: shooter buttons no longer cover the crosshair or weapon, strategy panels collapse, bigger buttons, a clear \"Strategy ⇄ Battle\" switch":"スマホ:シューターのボタンが照準や武器と重ならない。ストラテジーのパネルは折りたたみ式。ボタンが大きくなり、「ストラテジー ⇄ 戦闘」の切り替えも分かりやすく",
"Combined build: the v6.2 ore-vein crystals and extractors + grenades with a throw arc":"統合版:v6.2の鉱脈クリスタルと採掘機+投擲弾道つきグレネード",
"New in v6.4":"v6.4の新要素",
