"Click the marked vein ⛏ — the glowing crystals (RMB/Esc — cancel). Mark off-screen — click it to fly the camera there.":"印のついた鉱脈 ⛏(光るクリスタル)をクリック(右クリック/Esc — キャンセル)。マークが画面外ならクリックでカメラが飛ぶ。",
"Tap a spot for the {0}, then \"✔ Build\".":"{0}を置く場所をタップして「✔ 建設」。",
"Click a spot for the {0} (RMB/Esc — cancel).":"{0}を置く場所をクリック(右クリック/Esc — キャンセル)。",
"I am the Curator: I highlight the button and the spot on the map. \"✕\" turns me off.":"ボクはガイド。必要なボタンとマップ上の場所を光らせるよ。「✕」でオフ。",
"I am the Curator. I will suggest what to do as you play, highlighting the button and the spot on the map. Turn me off with \"✕\" here or the \"Curator\" button at the bottom right.":"ボクはガイド。戦闘中に何をすべきか教え、ボタンとマップ上の場所を光らせるよ。オフにするにはここの「✕」か、右下の「ガイド」ボタン。",
"The Swarm is at the base! \"All army\", then long-tap the enemies. A turret at the base helps too.":"スウォームが基地に迫ってる!「全軍」を選んで、敵を長押し。基地のタレットも役に立つ。",
"The Swarm is at the base! Select troops (box or Ctrl+A) and RMB the enemies. A turret (Z) helps too.":"スウォームが基地に迫ってる! 部隊を選んで(範囲選択かCtrl+A)敵を右クリック。基地のタレット(Z)も役に立つ。",
"Camera: drag the map with a finger, two fingers — zoom and rotate. Move the camera.":"カメラ:指でマップをドラッグ、二本指でズームと回転。カメラを動かそう。",
"Camera: WASD or screen edges, wheel — height, Q/E — rotate. Move the camera.":"カメラ:WASDか画面端、ホイールで高さ、Q/Eで回転。カメラを動かそう。",
"No builders — and nothing gets built without them. Select the HQ — click it or the \"⌂ HQ\" button.":"工兵がいない。工兵なしでは建物を1つも建てられない。司令部を選ぼう。クリックするか「⌂ 司令部」ボタンを押す。",
"Order a builder — the \"⚒ Builder\" button in the HQ panel (50 ore).":"工兵を要請しよう。司令部パネルの「⚒ 工兵」ボタン(鉱石50)。",
"We need ore — let us put an extractor on an ore vein.":"鉱石が必要だ。鉱脈にエクストラクターを置こう。",
"Press \"Extractor\" (C) and place it on the glowing crystals of the vein — I marked it ⛏.":"「エクストラクター」(C)を押して、鉱脈の光るクリスタルの上に置こう。⛏で印をつけておいた。",
"Few troops. Select the HQ — squads are ordered there.":"兵力が少ない。司令部を選ぼう。分隊はそこで要請する。",
"Order an \"Assault squad\" in the HQ panel.":"司令部パネルで「突撃分隊」を要請しよう。",
"Points give ore. Select a squad — tap it or the \"◈ Squad\" button on the right.":"ポイントからは鉱石が入る。分隊を選ぼう。分隊をタップするか、右の「◈ 分隊」ボタン。",
"Points give ore. Select a squad — tap it or the \"◆ Army\" card at the top.":"ポイントからは鉱石が入る。分隊を選ぼう。分隊をタップするか、上の「◆ 軍」カード。",
"Points give ore. Select a squad — click it or its card in the \"◆ Army\" panel on the left.":"ポイントからは鉱石が入る。分隊を選ぼう。分隊をクリックするか、左の「◆ 軍」パネルのカード。",
"Long-tap point {0} — the squad goes to capture it.":"ポイント{0}を長押しすると、分隊が制圧に向かう。",
"RMB on point {0} — the squad goes to capture it.":"ポイント{0}を右クリックすると、分隊が制圧に向かう。",
"POINT ":"ポイント ",
"The base is under attack — let us build a turret.":"基地が攻撃されている。タレットを建てよう。",
"Press \"Turret\" (Z) and place it at the base, facing the enemy.":"「タレット」(Z)を押して、敵側の基地の近くに置こう。",
"Enough ore for a mech factory — it makes tanks and vehicles.":"メカ工場を建てる鉱石は足りてる。戦車や車両はここで作る。",
"Press \"Mech factory\" (B) and place it at the base (a flat spot inside the dashed ring).":"「メカ工場」(B)を押して基地に置こう(点線の輪の内側の平地)。",
"{0} is idle — select it and give an order: {1} a point or an enemy.":"{0}が遊んでいる。選択して命令を出そう。ポイントか敵に{1}。",
"The mech factory is ready. Select it to order a tank.":"メカ工場が完成。選んで戦車を要請しよう。",
"Order a \"Tank\" in the factory panel.":"工場パネルで「戦車」を要請しよう。",
"More extractors — more ore. There is a free vein nearby.":"エクストラクターが増えれば鉱石も増える。近くに空いている鉱脈がある。",
"\"Extractor\" (C) on the marked vein ⛏.":"印のついた鉱脈 ⛏に「エクストラクター」(C)を置こう。",
"Pick a power and click an enemy cluster.":"攻撃を選んで、敵の密集地点をクリックしよう。",
"Command points are piling up — the \"✺ Powers\" tab: artillery, recon, drop pod.":"指揮ポイントが溜まっている。「✺ 攻撃」タブ:砲撃、偵察、ドロップポッド。",
"Low on ore? Tap \"ORE\" at the top — see where income comes from and how to boost it.":"鉱石が足りない?上の「鉱石」をタップすると、収入源と増やし方が分かる。",
"Want to fight yourself? Select a squad and press \"▶ Possess\".":"自分で戦いたい?分隊を選んで「▶ 憑依」を押そう。",
