"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"財団の重機関銃兵が、スケルトン入りの本格3Dモデルに。待機、歩行、銃を構えての突撃、移動しながらの射撃、撃破時のやられモーションに対応",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"モデルは隕石の表面の法線に沿って立ち、照準に合わせて上半身を向け、機関銃を構える。遠くではアニメーションの更新頻度を下げてFPSを維持",
