"Barracks":"兵舎",
"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"歩兵:突撃分隊、重機関銃兵、狙撃兵、偵察兵、ドロップポッド。装甲と武器の強化。",
