"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"工兵がここにクリスタルを納品する。クリスタル鉱床のそばに建てよう — 運ぶ距離が短くなり、鉱石が増える。",
"Tanks and vehicles. Requires Barracks.":"戦車と車両。兵舎が必要。",
"Autonomous combat drones. Requires Barracks.":"自律戦闘ドローン。兵舎が必要。",
"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"ジェットパックIIと空挺兵(ジェットパックのエリート)。メカ工場が必要、6:00に解放。",
"Forward base at an owned point: builders, crystal drop-off, reinforcement.":"自軍の制圧ポイントに建てる前線基地:工兵、クリスタル納品、増援。",
"Unlocks at {0}":"{0}に解放",
