"Jetpacks and aircraft unlock later — time to set up anti-air and turrets. Build Barracks and a Mech factory meanwhile.":"ジェットパックと航空機は少し後に解放される — 対空砲と砲塔を設置する時間はある。それまで兵舎とメカ工場を建てよう。",
"Lone heavy gunner":"一匹狼の重機関銃兵",
"Crystals nearby are depleted — builder is idle":"近くのクリスタルが枯渇 — 工兵が待機中",
"A crystal field is depleted":"クリスタル鉱床が枯渇した",
"carrying ore (+{0})":"鉱石を運搬中(+{0})",
"mining crystals":"クリスタルを採掘中",
"No crystal field near a drop-off":"納品先の近くに利用できるクリスタル鉱床がない",
"Mine crystals: the builder picks up a load at a green field and carries it to the HQ/depot. Or RMB the crystals.":"クリスタル採掘:工兵が緑の鉱床で荷を積み、司令部/貯蔵庫へ運ぶ。またはクリスタルを右クリック。",
