"Back to the normal device mode":"通常のデバイスモードに戻す",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"別のデバイス向けトレーニングは、そのモードでページを再読み込みします(PC — マウスとキーボード、スマホ — タッチ。PCでタッチを試すにはChromeで F12 → スマホアイコン)。",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"トレーニング×4:PC用とスマホ用に、「ストラテジー」と「シューター」の段階式レッスンをそれぞれ用意。ダミーのいる安全なサンドボックス、必要なボタンのハイライト、矢印、アニメーションするキー・マウス・ジェスチャー。ステップは本当の操作をしたときだけ達成扱い、「ステップをやり直す」、上部に進行状況、最後に報酬",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"「トレーニング」メニューには、お使いのデバイス向けのレッスンが表示されます。「他を表示」で、どのデバイスでも4つすべてを表示。「旧トレーニング(v7.1)」も残っています",
