"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"左 — 移動、右 — 視点 · 敵をタップ — ロケット弾/グレネード · 2回タップ — リフレックス · 3回タップ — 砲撃",
