"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"敵が多い — 右側の何もない場所をダブルタップ:リフレックスで時間が遅くなる。",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"敵の集団に照準を合わせて3回タップ — 砲撃。",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"左の指で移動、右の指で視点操作。照準が敵に合うと自動で撃つ。",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"左端の ⇑ — ジェットパック:タップでジャンプ、長押しで飛行。",
"Old v7.2 layout":"v7.2の旧レイアウト",
"Drag a finger on the right half of the screen — a look stick appears under it.":"画面の右半分で指をドラッグ — 指の下に視点スティックが出る。",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"画面の左側をタッチしてスライド — 指の下にスティックが出る。緑のマーカーまで進もう。",
"Hold the \"Jet\" button at the left edge.":"左端の「ジェットパック」ボタンを押し続ける。",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"右スティックでダミーに照準を合わせる — 照準が合うと兵士が自動で撃つ。",
"Tap the dummy on the screen — a rocket flies.":"画面上のダミーをタップ — ロケット弾が飛ぶ。",
"Tap the dummy — a grenade flies in an arc, right at it.":"ダミーをタップ — グレネードが弧を描いて命中する。",
"Double tap an empty spot on the right quickly.":"右側の何もない場所をすばやくダブルタップ。",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"低スペックのスマホ向けライトモード:解像度を下げ、影と歪みなし、ボットとパーティクルは半分、30 FPS上限。FPSが25未満になると自動で解像度を下げます。スマホでは初期状態でオン(設定 → グラフィック →「ライトモード」、またはリンクに ?lite=1 / ?lite=0)。",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"スマホ:新しい操作。左 — 移動、右 — 視点(どちらのスティックも指の下に出る)。左の指だけなら「オート」、右の指も使うと、照準が敵に合っている間だけ兵士が自動で撃つ。敵をタップ — ロケット弾かグレネード、2回タップ — リフレックス、3回タップ — 砲撃。リロードは自動。ジェットパックは左端のボタン。画面下の角は空き、ミニマップは角に配置、ヒントは×で閉じられ、目標は折りたためる。旧レイアウト:設定 → スマホ。",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"ヒント(ポップアップとガイド)は設定のスイッチ1つで切り替え。操作中のユニット(兵士や車両の種類)はHUDの「あなた:…」ラベルで表示。ライフルと機関銃のスコープは透過式。「アーセナル」パネルは右にドッキングし、折りたたみとオン/オフが可能。「分隊なしでソロ」(J)は廃止。AI戦略官は同じ台詞を繰り返さなくなった。戦車には車体に対する砲塔の向きインジケーターを追加。ストラテジートレーニング開始時にカーソルが消える問題を修正。",
