"Voice of hints & curator":"ヒントとガイドの音声",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"スマホ:スティックは3モード。左のみ — 「オート」(強いマグネット、弾は弱め)。右のみ — 照準が自動でオン、マグネットは強く、精度も上がる。両方 — 照準なし、マグネットと精度は弱め。右の 👁 ボタンでHUDの表示/非表示。",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"スマホ:ストラテジーを簡略化 — 工兵と建物のみ。左のカード(工兵、司令部、兵舎…):タップでカメラが移動し、下のバーに建設/生産の項目が出る。「戦闘へ」は左上。軍は自動で戦う。フルのストラテジー — 設定 → スマホ。",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"憑依 — スイッチは「分隊」と「車両」の2つ(スマホでは車両は初期状態でオフ — AIが運転)。車両がオフのときは、味方車両の横で E(スマホは右のボタン)を押すと砲に着く:車両は自動で走り、あなたが撃つ。従来の「兵種の順序カスタム」は「詳細設定」にあります。憑依するとユニットが無線で応答します。",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"スマートヒント:基本ヒントは2回目の起動後に自動で消えますが、一度も使っていない機能はゲームが教えてくれます。スイッチは基本/上級/レア、ヒントとガイドの音声は別枠。",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"リフレックスはキルでチャージされる(連続キルはより多く)。仲間が遅れたり倒れたりすると、AI戦略官が新しい兵士を降下させる(通常の増援より高コスト)。v7.2gfxのグラフィックとサウンドを統合:もくもくと広がる爆発、煙、破片、坑道とクレーターの音響。ビルド日付も正しい日付になった。",
