"Cinema: everything built":"シネマ:全て建設済み",
"both bases built and upgraded — for footage":"両方の基地を建設・強化済み — 撮影用",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"シネマモード — 画面分割:左はAI戦略官ボット(基地と軍の俯瞰)、右は一人称のシューターボット。下部のボタン(キー S、P):「画面分割」と「★ 全て建設済み」 — 撮影用に両方の基地を建設・強化済みにします。",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"コアと隕石を貫くトンネルはもう存在しない — 隕石は一枚岩で、戦闘は地表のみ。",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"スマホ:👁 でHUDを隠せるが、ジェットパック、⇆、スティック、目標マーカーは残る。「◎ エイム」(右指のみ)— 明らかに強く広いマグネット。3モードのマグネット強度は 設定 → 操作 →「詳細」。車両の砲では、ボタンが「降りる」になる。",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"トレーニング:スマホではスマホ用のみ、PCではPC用のみ。4つすべて「🛠 開発者」メニューにある。開発者モードと武器庫は1つのメニューにまとめた(戦闘中は右上の「🛠 メニュー」、PCではF8も可)。",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"グラフィックスタイル「Dendy(8ビット)」と「16ビット」:設定 → グラフィック →「グラフィックスタイル」(詳細は ⚙ ボタン)。マッチ開始から約10秒間のFPSが24未満なら、Dendyが自動でオンになる(20未満が続くとさらにドットが大きくなり、120ライン)。上部の「通常に戻す」通知で、通常のグラフィックに完全に戻せる。メニューでの自分の選択が常に優先される。",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D環境モデル(廃墟、残骸、要塞)— 高評価のものだけで、必要に応じて読み込む。オフにするには:設定 → グラフィック →「新しい3D環境モデル」。",
