"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"兵士による建設:味方の建設現場でE(スマホでは「入る」)— 兵士が自分で建て、近くの分隊員が手伝う。工兵が手一杯のときは、戦略官が「建設現場」マークで手伝いを頼んでくる。",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"AI戦略官のマーク:AI戦略官が近くの敵の密集地点に ⌖ を置くと、8秒後に砲撃が着弾し、近くの味方MLRS「グラード」が一斉射撃する。ストラテジストモードからの自分の砲撃にも「グラード」の支援が付く。",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"貨物コンテナや墜落した衛星にある武器の補給箱(📦 は70 mから見える):E — 90秒間の重機関銃、焼夷弾またはロケット弾、さらにグレネード満タン。匍匐:Ctrl — 伏せる / 立ち上がる(姿勢が低く、狙いは安定するが移動は遅い)。",
