"Do not like the new version — play the one you are used to. The choice is remembered; every version has its own saves and settings (these stay safe). An old version is loaded only when chosen.":"新バージョンが合わないなら、慣れたバージョンで遊べる。選択は記憶され、各バージョンに専用のセーブと設定がある(消えない)。旧バージョンは選んだときだけ読み込まれる。",
