"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"「▶ 今すぐプレイ」— メニューの最初のボタン。天空ポータルの下を短く飛行して、そのまま戦闘へ(任意のキーかタップでスキップ)。",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"命中の手応えを強化:金属音と火花、照準付近のキルマーカー(ヘッドショットは黄色)、連続撃破×N、爆発による滑らかなシェイク、重要な撃破でスローモーション。シェイク、スローモーション、ヒントは設定でオフにできる。",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"マッチ結果:時間、撃破数、最高連続撃破、★ MVPと最優秀分隊、マッチカード — 「⇪ 共有」でPNGかゲームへのリンクを共有。",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"リソースの下、左側に「今やること」ヒント:戦略官の指令、制圧するポイント、スウォームの攻勢。✕ かF7で折りたたみ。",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"タブを閉じるか非表示にすると戦闘は自動セーブされる — メニューの「⟲ 続ける」から再開。",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5は「🕘 ゲームバージョン」メニューに残してある — 新バージョンが合わなければどうぞ。匿名統計(名前やメールは収集しない)を送信するようになった。設定でオフにできる。",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"「今すぐプレイ」、命中フィードバック、共有カード付きマッチ結果、「今やること」ヒント、オートセーブ",
"and older: v7.5, v7.4, milestones v1–v7.0":"旧バージョン:v7.5、v7.4、節目 v1–v7.0",
"New in v7.6":"v7.6の新要素",
"NEW IN v7.6":"v7.6の新要素",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"マッチ前に勢力を選べる:「コンソーシアム」(重い装甲服を着た重装歩兵、装甲と砲撃)か「スウォーム」(速度、ドローン群、歪みを伴う重い射撃)。もう一方はAIが担当。選択は記憶される。",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"各勢力に専用の車両と固有要素がある:コンソーシアムは戦車「ライノ」と「セラマイト装甲板」、スウォームは「ドローン群」と「フェーズ・ジェットパック」。バランスはボット同士のマッチで検証済み。",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"爆発クレーター: 砲撃、ロケット弾、戦車砲が隕石に穴を掘る — 中を歩いたり走ったりでき、遮蔽にも使える。",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"兵士の三人称視点(V、設定は記憶される。スマホでは操作設定から)と、砲弾の着弾点を示すマーカー付きのなめらかな車両カメラ。",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6は「🕘 ゲームバージョン」メニューに残してあるので、新版が合わなければ戻せる。",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"コンソーシアム / スウォームの陣営をマッチ前に選択、爆発クレーター、三人称視点",
