"Anomaly ahead! The vein is singing — go around!":"前方に異常現象! 鉱脈が歌っている — 迂回しろ!",
"Hear that hum? A singing vein. Keep clear!":"あの唸りが聞こえるか? 歌う鉱脈だ。近づくな!",
"Anomaly! The air is swirling — a whirlpool, go around!":"異常現象だ! 空気が渦巻いている — 渦だ、迂回しろ!",
"Rocks floating in the air… A whirlpool! Stay out!":"岩が宙に浮いてる…渦だ! 入るな!",
"Anomaly ahead — it is crackling with current!":"前方に異常現象 — 電流でバチバチ鳴っている!",
"Rods and lightning — a Crackler. It loves armour!":"棒と稲妻 — クラックラーだ。装甲が大好物だぞ!",
"Anomaly! The ground shimmers with heat — a Brazier!":"異常現象だ! 地面が熱で揺らいでいる — 火鉢だ!",
"Careful, a Brazier underfoot!":"気をつけろ、足元に火鉢だ!",
"Anomaly — green mist! Acid, hold your breath!":"異常現象 — 緑の霧だ! 酸だ、息を止めろ!",
"The mist is drifting our way, go around!":"霧がこっちに流れてくる、迂回しろ!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"異常現象だ! 空気がガラスみたいだ — レンズだ、弾が曲がる!",
"Everything is warping… a Lens nearby!":"景色が歪んでる…近くにレンズがある!",
"Ha! An enemy walked right into the anomaly!":"はは! 敵が異常現象に突っ込んだぞ!",
"Got him! Lure them into anomalies!":"引っかかったな! 敵を異常現象に誘い込め!",
"Beautiful zap! One less tin can.":"派手にやったな! ポンコツが一台減った。",
"The anomaly got me!":"異常現象にやられた!",
"Ow! Don't go in there!":"いてっ! そこには入るな!",
"Discharged! It is dormant now.":"放電した! これで休眠状態だ。",
"Clear, the anomaly is discharged.":"クリア、異常現象は放電済み。",
"They say veins hide artifacts. Only first the vein sings…":"鉱脈にはアーティファクトが隠れてるって話だ。ただし最初に鉱脈が歌うんだ…",
