"Supply drop":"補給ボックス",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"味方戦力の近くにボックスを投下: 弾薬、グレネード、ロケット弾、武器パーツ、修理キット。",
"\"Grad\" rocket strike":"「グラード」ロケット攻撃",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"3秒後に広範囲へロケット弾16発 — 砲撃より速く、より広い。",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"支援: ボックス、偵察、「グラード」、砲撃(続けて1〜4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"警告: スウォームの「グラード」がそちらのエリアに着弾する!",
"Warning! Rocket salvo on our position!":"警告! 我々の陣地にロケット一斉射撃!",
"take the supply crate":"補給ボックスを取る",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"隕石上の異常現象(第1波): 「歌う鉱脈」 — 緑に輝くクリスタルで、唸りを上げ、周囲の全員にリズミカルなパルスを浴びせる。「渦」は引き寄せて叩きつけ、「クラックラー」は棒の間で稲妻を走らせ、「火鉢」は足元で燃え上がり、「酸の霧」と「レンズ」(弾道と視界を曲げる)は漂っている。",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"異常現象は事前に感じ取れる(唸り、輝き、陽炎)。グレネード、ロケット弾、ボルト(近くでE)で放電させると休眠状態になり、プラスとマイナスを持つアーティファクトを残すこともある。分隊が無線で警告し、敵(と味方)もたまに迷い込む — 誘い込め!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"指揮点で使える支援: 戦闘中に4種(スマホでは📡) — 補給ボックス、偵察スキャン、「グラード」ロケット攻撃、照準位置への砲撃。戦略家は偵察後にのみマップ上で異常現象を確認できる。",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"補給ボックスは古い探検隊の遺跡、司令部の近く、完成した建物の横にある: 弾薬、グレネード、ロケット弾、武器パーツ(アタッチメントを解放)。",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7は「🕘 ゲームバージョン」メニューに残してある。異常現象は設定でオフにできる。",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"異常現象(「歌う鉱脈」ほか5種)、ボルトとグレネードでの放電、アーティファクト、CPで使う支援、補給ボックス",
"and older: v7.7, v7.6, milestones v1–v7.0":"過去のバージョン: v7.7、v7.6、マイルストーンv1〜v7.0",
"New in v7.8":"v7.8の新要素",
"NEW IN v7.8":"v7.8の新要素",
"Close":"閉じる",
"Anomalies on the meteor":"隕石上の異常現象",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"隅の☰で一時停止メニューを開く: 続ける、最初からやり直す、トレーニング、グラフィック、設定、メインメニュー(確認あり)。スマホ: 右上の☰(戦闘アクションは「⚡ アクション」タイル)、PC: 右上の「☰ メニュー」ボタンまたはEsc。",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"グラフィックは常に標準がデフォルト — Dendyは自分で選んだ時だけ: 「グラフィック: 標準 / Dendy (8ビット) / 16ビット」の切り替えはメインメニューと一時停止メニューにある。ゲームが大きく重い場合は「Dendyをオン」ボタン付きのヒントが出る。",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"スマホとタブレット: 右側の「✋」アクションボタンは、近くにできることがある時だけ表示される — 「取る」(隠し場所、ボックス)、「乗る」(車両、タレット、砲)、「建設」、「降りる」、異常現象での「ボルト」。ハイライトされたオブジェクトを直接タップしてもいい。",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"スマホでのストラテジー: 指を約0.3秒押し続け(スマホが振動し、黄色いリングが出る)、そのままドラッグ — 範囲選択。通常のスワイプはカメラ移動。右側に「範囲」ボタンもある。トレーニングの「範囲」ステップでは、分隊のタップ選択も有効。",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"スマホ: 小さいボタンが押しやすくなり、📡支援リストが大きくなり、ストラテジーのパネルが一時停止画面や結果画面に重ならなくなった。v7.8は「🕘 ゲームバージョン」メニューに残してある。",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"スマホとPCで☰メニュー、Dendy自動切り替えの廃止、タッチ操作の「✋」ボタン、スマホでの範囲選択",
