"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"iPhoneで全画面にするには: 「共有」⬆ → 「ホーム画面に追加」 — Safariのバーなしでゲームが開く。",
"Open portal-meteor.pages.dev for that.":"そのためにportal-meteor.pages.devを開いてくれ。",
