"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"ヒーロー(各陣営1体): 自力で敵ゾーンをテレポートして回りロボットを切り裂く。乗っ取れば手動で操作できる。",
