"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ 自動: 自力で敵ゾーンを跳び回って斬る。スティック / WASDで1.5秒間停止",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ 手動: 敵をタップ — ダッシュして斬る、スワイプ — 斬撃、🛡 — ガード",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ 手動操作: 左クリック — 刀、右クリック — ガード、Shift — ブリンク、Q — 手裏剣、G — テレポート",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ ロボ忍者:敵をタップ — ダッシュして斬撃、右側をスワイプ — 斬り払い、● — 攻撃、🛡 — ブロック(タイミングよく=パリィ)、⇑ — ブリンク、✦ — 手裏剣、◎ — テレポート、AUTO — 自動操作",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ ロボ忍者:左クリック — 刀(長押し — 強斬り)、右クリック — ブロック(タイミングよく=パリィ)、Shift/Z — ブリンク、Q — 手裏剣、G — 照準位置へテレポート、空中でジャンプ — 二段ジャンプ/壁走り、{0} — AUTO",
