"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Portal Meteor ラジオ:EDMITRY の100曲以上をゲーム内で再生 — 📻ボタン(PC:5キー、[ ] — 曲送り)。音楽は必要に応じてストリーミングされ、ゲームを重くしません。音量と自動再生は設定で変更でき、「Spotifyで聴く」リンクもあります。",
