"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"右の📻 — Portal Meteor ラジオ:戦闘中に EDMITRY の音楽を流せる。",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Portal Meteor ラジオ:戦闘中に EDMITRY の音楽を流せる。[ ] — 曲送り。",
"Radio Portal Meteor (EDMITRY): volume":"Portal Meteor ラジオ(EDMITRY):音量",
"Radio: start by itself in battle":"ラジオ:戦闘中に自動で開始",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"ロボ忍者:刀を持つサイボーグ。兵舎で研究「シャドウプロトコル」を完了すると解放される(メカ工場が必要)。自分で敵ゾーンへテレポートし、敵を斬り裂き(血は出ず火花が散る)、ダッシュや手裏剣を使い、敵の忍者と決闘する。「附身」すればAUTOモードか手動操作が可能(スマホでは専用ボタン)。",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Portal Meteor ラジオ:EDMITRY の103曲をゲーム内で再生。5キー(割り当て変更可)、スマホでは ☰ → 設定 → サウンド。音量と「戦闘中に自動再生」は設定で変更でき、爆発音や無線の声の間は音楽が小さくなる。",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"新言語:ウズベク語とタジク語 — 完全対応、中国語・スペイン語・ポルトガル語 — 一部対応。メニューの「新規マッチ」の隣に新しい言語選択を追加。",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"スマホ:「アイコンを隠す」👁 で残りのボタンを右端のすっきりした列にまとめる。縦画面での重なりを解消。iPhone — ゲームが Safari のジェスチャーと干渉しなくなり、「共有 → ホーム画面に追加」で全画面起動できる。",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1 より:隅の ☰ メニュー(一時停止、リスタート、トレーニング、グラフィック)、Dendy 自動切替の廃止、スマホの ✋ アクションボタン。v7.8.1 と v7.8 は「🕘 ゲームバージョン」メニューに残してある。",
