"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"味方がときどき助けを求めてくる:無線の声、「要請」カード、✋マーカー。分隊が釘付けにされている — 近くの敵を倒せ。報酬:基地からポッドで兵士、バギーの荷台の銃、砲手席、軌道上からの援護。不要なら ✕ か無視でOK。",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"ベテラン偵察兵「夜梟」がクエストを持ちかけてくる。Y — 受諾(N — 辞退)。★マーカーへ行き、見張りを倒して、パイロットのそばに3秒間立て — 彼が君の分隊に加わる。",
