"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"基地の中枢:小隊、工兵、空降舱、研究。司令部を失えば敗北。",
"Produces: ":"生産: ",
"Launch pad":"発射台",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"司令部横のサイロ:ここから空降舱、補給箱、爆撃機が天空ポータルを通って目標へ発射される。上には建設できない。",
"Economy":"経済",
"Key building":"重要施設",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"弱点——後部(エンジン):ダメージ×{0}。主砲、機関銃タレット2基、ロケットポッドを装備。旋回が非常に遅い——側面から回り込め。",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"弱点——腹部下の発光コア:下からのダメージ×{0}。歪曲ビームと範囲踏みつけ攻撃。バリアをまたぐ——距離を保ち、固まるな。",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"有効:航空爆弾と砲撃(×{0})、ロケット弾(×{1})、絨毯爆撃。銃弾はほぼ無効(×{2})。",
"Faction":"陣営",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"高速な機体、ドローンの群れ、トンネル、再生。歩兵は軽いが速い。砲とレールの威力が高い。",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"パワーアーマーの重装歩兵、コンクリート壁、修理、砲撃。遅いが頑丈。",
